 if(argc!=2)return 2;auto home=std::filesystem::temp_directory_path()/("dome-rest-vrm-length-"+std::to_string(getpid()));std::filesystem::create_directories(home);struct Cleanup{std::filesystem::path p;~Cleanup(){std::error_code ec;std::filesystem::remove_all(p,ec);}}cleanup{home};const auto source=home/"source.vrm";vrm_source_fixture::source_variant(argv[1],source,2);ImportAuthoringOptions options;options.paint_resolution=64;auto prepared=prepare_authoring_import(Scene{},source,options);auto scene=prepared.scene;auto selected=prepared.objects.front();const auto old=scene.encode();RigRestJointEdit edit;edit.joint=scene.object(selected).deformation->humanoid->joints.at("head");edit.world_length=.37f;author_rig_rest(scene,selected,{&edit,1});const auto fitted=scene.encode();check(old!=fitted&&scene.object(selected).rig_source,"A genuine native-only bone-length edit captures the complete actual source");check(Scene::decode(fitted).encode()==fitted,"Native projects retain authored VRM localY length exactly");const auto output=home/"old.vrm";export_vrm(scene.surfaces(),output);auto imported=prepare_authoring_import(Scene{},output,options);for(auto id:imported.objects){const auto&d=*imported.scene.object(id).deformation;const auto head=d.humanoid->joints.at("head");check(d.skeleton->bones.at(head).length==scene.object(selected).deformation->skeleton->bones.at(edit.joint).length,"Every real native skin freshly reimports the exact authored localY head length");}
